node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up order ORD-420D7A
// The order_id format might be different in the DB. Let me check.
let orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%420D7A%' OR order_id LIKE '%ORD%420D7A%'\").all();
console.log('Orders matching ORD-420D7A:', orders.length);
if (orders.length === 0) {
  // Check if order IDs use a different format
  let sample = db.prepare('SELECT order_id FROM orders LIMIT 10').all();
  console.log('Sample order IDs:', sample);
}
orders.forEach(o => console.log(JSON.stringify(o, null, 2)));
"

